import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Assistant IA (MCP) et propositions","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/18-mcp.md","filePath":"generated/modules/18-mcp.md","lastUpdated":null}'),r={name:"modules/18-mcp.md"};function d(i,e,o,l,p,u){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="assistant-ia-mcp-et-propositions" tabindex="-1">Assistant IA (MCP) et propositions <a class="header-anchor" href="#assistant-ia-mcp-et-propositions" aria-label="Permalink to &quot;Assistant IA (MCP) et propositions&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/18-mcp">spécification complète</a></span></p><p>Assistant IA du commerçant branché par le protocole MCP : il répond aux questions (lecture) et peut préparer des actions qu&#39;un responsable valide toujours. Le jalon 1 du projet « écriture » (VEN-45 → VEN-48, 16 et 17/11/2026) pose le socle générique : registre de types, allumage par type, familles de propositions réglées par le gérant, par clé et par connexion, écran de décision unique sur le back-office et les deux apps caisse. Aucun type nouveau n&#39;est ouvert : les trois actions existantes (bon de commande, prix, alerte de fraude) tournent sur le socle. Les lectures (outils, OAuth, démonstration) restent décrites dans la vue d&#39;ensemble.</p><div class="kpis"><div><b>10</b><span>faites</span></div><div><b>1</b><span>partielles</span></div><div><b>8</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="propositions-de-l-assistant-—-socle-generique" tabindex="-1">Propositions de l&#39;assistant — socle générique <a class="header-anchor" href="#propositions-de-l-assistant-—-socle-generique" aria-label="Permalink to &quot;Propositions de l&#39;assistant — socle générique&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Registre des types de proposition</strong><br><span class="muted">Chaque action que l&#39;assistant peut préparer est décrite en un seul endroit du serveur : ce qu&#39;il peut remplir, ce qu&#39;il n&#39;a jamais le droit de toucher, qui valide et où. Ajouter un type devient déclaratif et ne peut plus affaiblir les garde-fous.<br><i>Les trois types de VEN-34 (bon de commande, changement de prix, traitement d&#39;une alerte) sont migrés sans changer leur comportement. Garde des exclusions (fiscal, argent, sécurité et accès, abonnement, envois, suppressions, TVA) vérifiée au démarrage et par test ; champs fermés par type ; propositions groupées (100 lignes au plus, tout ou rien) ; demande répétée reconnue sans doublon ni quota consommé. Aucun type nouveau n&#39;est ouvert à ce jalon. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-84, RG-MCP-106, RG-MCP-107, RG-MCP-108, RG-MCP-115, RG-MCP-116, RG-MCP-117, RG-MCP-119, RG-MCP-122, RG-MCP-123, RG-MCP-129, RG-MCP-130, RG-MCP-132</td><td>VEN-45, VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Allumage de chaque type par l&#39;exploitation</strong><br><span class="muted">Vendora allume les types d&#39;action un par un : un type nouveau est livré éteint et ne devient disponible qu&#39;après sa revue de sécurité.<br><i>Variable d&#39;exploitation par type ; un type éteint se comporte comme l&#39;interrupteur général éteint pour lui seul (création refusée, outil non listé, propositions existantes toujours décidables). Migration V124 : les accès qui proposaient déjà gardent leurs trois types sans geste. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-104, RG-MCP-110</td><td>VEN-45</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Familles de propositions réglées par le gérant</strong><br><span class="muted">Dans Réglages › Assistant IA, le propriétaire ou un administrateur choisit, famille par famille, ce que l&#39;assistant a le droit de proposer (catalogue, achats, anti-fraude…). Éteint par défaut pour un nouveau commerce.<br><i>Huit familles existent (catalogue, stock, achats, restaurant, clients, réglages, appareils, anti-fraude) ; seules Catalogue, Achats et Anti-fraude portent aujourd&#39;hui des actions. Réglage réservé à la session d&#39;un propriétaire ou d&#39;un administrateur : une clé ou un jeton reçoit 403, un assistant ne peut jamais élargir ses droits ; changements inscrits au journal d&#39;audit. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-109, RG-MCP-111</td><td>VEN-45, VEN-48</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Familles de propositions par clé d&#39;API et par connexion d&#39;assistant</strong><br><span class="muted">Quand le gérant crée une clé « Assistant IA » ou autorise la connexion d&#39;un assistant, il coche les familles que cet accès peut proposer ; rien n&#39;est coché d&#39;office, et une clé ne reçoit jamais une famille d&#39;elle-même.<br><i>Bloc « Préparer des propositions » sur le formulaire de clé et sur l&#39;écran de consentement OAuth (FR / EN / AR, clair / sombre) ; avertissements quand la lecture du domaine manque ; badges « Lecture et propositions » / « Lecture seule » sur les accès ; nouvelle famille de lecture « Réglages » au consentement. Une seule portée d&#39;écriture reste : proposals:write. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-111, RG-MCP-112</td><td>VEN-45, VEN-48</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Écran de décision générique des propositions</strong><br><span class="muted">Un seul écran, le même pour toutes les actions que l&#39;assistant propose : ce qui change (avant → après), les chiffres de Vendora datés, le risque, puis valider ou refuser au back-office, ou sur la caisse avec le PIN d&#39;un responsable.<br><i>Le serveur fournit le modèle d&#39;affichage (cinq blocs fermés, valeurs typées) : les écrans ne connaissent plus les types. Filtre par famille, tri par risque puis échéance, saisie du validateur, case de confirmation renforcée avant le PIN, états (déjà traitée, périmée avec la raison, expirée, appliquée), prix de l&#39;entreprise lisible sur les caisses, « Back-office seulement » pour les types qui s&#39;y décident. Back-office, iPhone / iPad, téléphone et tablette Android ; français, anglais, arabe (RTL), sombre. Écarts restants listés dans le README des captures (E1 à E8). Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-91, RG-MCP-113, RG-MCP-114, RG-MCP-120, RG-MCP-121, RG-MCP-131</td><td>VEN-45, VEN-47</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a></td></tr><tr><td><strong>Outils de proposition de l&#39;assistant (fabrique d&#39;outils)</strong><br><span class="muted">L&#39;assistant ne voit que les actions que son accès peut réellement proposer ; ses montants sont compris sans ambiguïté et ses refus lui sont expliqués en clair.<br><i>Fabrique d&#39;outils d&#39;écriture dans le serveur MCP (un outil par objet métier, paramètre « action » fermé) ; liste d&#39;outils calculée d&#39;après ce que l&#39;accès peut proposer ; montants lus sans facteur 1 000 ni forme illisible acceptée (chiffres arabes compris) ; refus de famille relayés ; une seule écriture possible, la création d&#39;une proposition (liste blanche testée). Évaluations d&#39;écriture ajoutées au jeu de référence. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-100, RG-MCP-101, RG-MCP-128</td><td>VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Suivi de ses propositions par l&#39;assistant</strong><br><span class="muted">L&#39;assistant peut dire où en sont les propositions qu&#39;il a préparées (en attente, appliquées, refusées, expirées) sans jamais voir la justification du responsable ni son commentaire.<br><i>Outil list_proposals côté MCP et vue GET /api/v1/agent-proposals/mine côté serveur, bornée par la portée de lecture de l&#39;accès ; sans justification, sans commentaire libre du refus et sans nom du validateur ; absent de la démonstration publique. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-127</td><td>VEN-45, VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr></tbody></table><h2 id="types-de-proposition-deja-livres-ven-34" tabindex="-1">Types de proposition déjà livrés (VEN-34) <a class="header-anchor" href="#types-de-proposition-deja-livres-ven-34" aria-label="Permalink to &quot;Types de proposition déjà livrés (VEN-34)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Bon de commande proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant prépare un bon de commande en brouillon à partir des besoins de réassort ; un responsable le relit et le valide, et le brouillon est créé à son nom.<br><i>Livré par VEN-34 (15/11/2026), migré sur le registre par VEN-45, rendu par l&#39;écran générique depuis le socle. Le bon reste un brouillon : jamais envoyé au fournisseur par l&#39;assistant.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Changement de prix proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose un nouveau prix de vente (ancien prix, nouveau, écart) ; seul le prix change, jamais la TVA ni la disponibilité ; un responsable valide, avec une case de confirmation au-delà de 30 % d&#39;écart.<br><i>Prix de l&#39;entreprise ou d&#39;un magasin, sous verrou commun des surcharges ; les ventes déjà faites gardent leur prix. Depuis le socle, la case « plus de 30 % » apparaît aussi sur la caisse avant le PIN et un prix de l&#39;entreprise se lit (sans se décider) sur les caisses.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Traitement d&#39;une alerte anti-fraude proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose d&#39;acquitter ou d&#39;écarter une alerte avec un motif ; le responsable relit, modifie le motif si besoin et décide : la décision ne s&#39;annule pas.<br><i>Motif pré-rempli par l&#39;assistant et modifiable, marqué comme tel ; résumé de l&#39;alerte composé par Vendora et traduit à la lecture (FR / EN / AR).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr></tbody></table><h2 id="types-de-proposition-livres-eteints-par-defaut-ven-54" tabindex="-1">Types de proposition livrés, éteints par défaut (VEN-54) <a class="header-anchor" href="#types-de-proposition-livres-eteints-par-defaut-ven-54" aria-label="Permalink to &quot;Types de proposition livrés, éteints par défaut (VEN-54)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Disponibilité d&#39;un produit proposée par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de rendre un ou plusieurs produits (20 au plus) indisponibles dans un magasin, ou de les remettre en vente ; un responsable valide au back-office, sur la caisse ou sur le téléphone de salle avec son PIN. Seule la disponibilité change : jamais le prix ni la TVA.<br><i>VEN-54 partie 1, développé, testé et fusionné le 18/11/2026, mais LIVRÉ ÉTEINT : le type PRODUCT_AVAILABILITY n&#39;est pas dans la liste par défaut des types allumés, Vendora l&#39;allume type par type, et il n&#39;est pas encore allumé sur le staging (décision d&#39;Ahmed à venir) ; statut « partiel » tant qu&#39;il n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_product_availability (store, 1 à 20 produits, available booléen). Seconde écriture dédiée « disponibilité seule » : prix et TVA de la ligne du magasin relus bruts et jamais remplacés (« hérité » reste hérité), prouvé sur cinq cas en base et par l&#39;API. Périmée si la fiche ou le magasin a changé entre-temps. Effet : produit retiré de la vente et du scan du magasin (caisses à leur prochaine synchronisation, menu en ligne tout de suite) ; une ligne déjà au panier reste vendable jusqu&#39;au relancement de l&#39;app. Rendu par l&#39;écran de décision générique, sans code d&#39;écran propre. Refusés : produits à variantes et variantes (jusqu&#39;à VEN-86), produit archivé, déjà dans l&#39;état demandé. Preuves sur la vraie stack : back-office, iPhone, iPad, Android téléphone et tablette, MCP (FR, arabe, sombre). Tests relancés de zéro le 18/11 : moteur partagé 858 (JVM) et 844 (iOS), serveur 901, MCP 347, Android 751, iOS 577, web 1 226, console 121, 0 échec.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-133, RG-MCP-134, RG-MCP-122</td><td>VEN-54</td><td><a href="/VendoraSystem-docs/preuves/2026-11-18-disponibilite-produit">📷</a></td></tr></tbody></table><h2 id="a-faire-—-jalons-suivants-du-projet-«-ecriture-»" tabindex="-1">À faire — jalons suivants du projet « écriture » <a class="header-anchor" href="#a-faire-—-jalons-suivants-du-projet-«-ecriture-»" aria-label="Permalink to &quot;À faire — jalons suivants du projet « écriture »&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Catalogue : fiches produit, catégories, modificateurs, écran de vente, import, prix groupés</strong><br><span class="muted">L&#39;assistant pourra proposer de créer, modifier, archiver ou mettre en promotion des produits, de gérer catégories, modificateurs et écran de vente, d&#39;importer un lot de produits et de changer plusieurs prix d&#39;un coup.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-49, VEN-50, VEN-51</td><td></td></tr><tr><td><strong>Stock : ajustements, pertes, lots, inventaires, seuils</strong><br><span class="muted">Proposer des mouvements de stock (toujours signés, jamais une valeur écrasée), le démarrage d&#39;un inventaire, des seuils d&#39;alerte et un stock initial.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-52</td><td></td></tr><tr><td><strong>Achats : réceptions, fournisseurs, prix fournisseur, transferts</strong><br><span class="muted">Compléter le bon de commande avec la réception, la création et la mise à jour de fournisseurs, leurs prix et les transferts entre magasins.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-53</td><td></td></tr><tr><td><strong>Restaurant : formules, fiches techniques, plan de salle, postes de préparation</strong><br><span class="muted">Proposer de publier une formule ou une fiche technique, de modifier le plan de salle et les postes de préparation (la disponibilité d&#39;un produit est livrée à part, éteinte).<br><i>VEN-54 partie 2, à cadrer à part : formules, recettes (fiches techniques), plan de salle, postes de préparation. La partie 1, la disponibilité d&#39;un produit, est livrée (fiche « Disponibilité d&#39;un produit proposée par l&#39;assistant »). Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-54</td><td></td></tr><tr><td><strong>Clients : programme de fidélité</strong><br><span class="muted">Proposer le réglage du programme de fidélité ; les données nominatives des clients restent en second temps, après avis juridique.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-55</td><td></td></tr><tr><td><strong>Réglages : magasin, ticket, apparence, rapports, canaux</strong><br><span class="muted">Proposer des réglages du commerce (hors fiscal, TVA, argent et sécurité, toujours exclus) : informations du magasin, profil de ticket, apparence, bornes, rapports, canaux, profils de salle.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-56</td><td></td></tr><tr><td><strong>Appareils : appairage, nom, réglages et configuration</strong><br><span class="muted">Proposer l&#39;ajout et le réglage d&#39;un appareil, sans que le code d&#39;appairage figure jamais dans une proposition.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-60</td><td></td></tr><tr><td><strong>Activité de l&#39;assistant et annulation d&#39;une proposition appliquée</strong><br><span class="muted">Voir ce que l&#39;assistant a fait et annuler ce qui peut l&#39;être.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-57</td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Types de proposition des jalons 2 à 7 (catalogue, stock, achats, restaurant, clients, réglages, appareils : 42 types prévus, listés dans docs/lots/MCP-ECRITURE-MATRICE.md), chacun livré éteint puis allumé après sa revue de sécurité.</li><li>Activité de l&#39;assistant et annulation d&#39;une proposition appliquée (VEN-57).</li><li>Écarts d&#39;écran laissés et points à faire acter par Ahmed : fiche de lot MCP-ECRITURE-SOCLE, section « Écarts constatés ».</li><li>Disponibilité d&#39;un produit (VEN-54 partie 1) livrée éteinte : allumage sur le staging puis revue de sécurité de la famille Catalogue, décision d&#39;Ahmed ; partie 2 (formules, recettes, plan de salle, postes de préparation) à cadrer.</li><li>Écarts laissés par la disponibilité d&#39;un produit (README des captures 2026-11-18-disponibilite-produit) : phrase de péremption qui ne dit pas « prix » ou « TVA » et change de cause à la relecture, texte du refus inverse de l&#39;outil MCP encore suivi de « (content.product) », résumé PIN en arabe dont les deux-points colle au nom latin, code-barres sous le nom visible sur Android seulement, bouton long sur deux lignes sur iPad en arabe.</li><li>Arabe de la disponibilité d&#39;un produit à faire relire par un natif ; produits à variantes refusés jusqu&#39;à VEN-86.</li><li>Écarts du socle soldés le 18/11 : parenthèse de l&#39;écart coupée en arabe sur la feuille PIN Android (corrigée), texte de l&#39;assistant absent de « Back-office seulement » sur les caisses (décision d&#39;Ahmed du 17/11), effectifs du filtre de famille des caisses comptés sur toute la liste (voulu : les caisses n&#39;ont pas de filtre de statut).</li></ul>',14)])])}const m=a(r,[["render",d]]);export{b as __pageData,m as default};
